L=$(ls -t /var/log/caddy/*.log 2>/dev/null | head -1); echo "лог: $L"; if [ -n "$L" ]; then echo '=== запити /dltemp/ ==='; grep -o '"uri":"/dltemp[^"]*' "$L" | tail -5; echo '=== останні /app/main.js зі статусом ==='; grep '/app/main.js' "$L" | tail -5 | python3 -c "import sys,json
for l in sys.stdin:
  try:
    d=json.loads(l); print(d.get('ts'), d.get('status'), d.get('request',{}).get('headers',{}).get('User-Agent',['?'])[0][:60])
  except Exception as e: print('parse',e)"; else echo 'логу немає'; fi
